INFERENCE_TYPES = (
    "AWS::Bedrock::Model",
    "AWS::Bedrock::AsyncInvoke",
    "AWS::Bedrock::AgentAlias",
    "AWS::Bedrock::InlineAgent",
)
KB_DATA_TYPE = "AWS::Bedrock::KnowledgeBase"
MANTLE_TYPES = (
    "AWS::BedrockMantle::Project",
    "AWS::BedrockMantle::Reservation",
    "AWS::BedrockMantle::CustomizedModel",
    "AWS::BedrockMantle::Environment",
    "AWS::BedrockMantle::Runtime",
    "AWS::BedrockMantle::Skill",
)
MANTLE_ROW = "Bedrock Mantle Data Event Logging"
COMPLETE_RECORD = {"logging": True, "text_delivery": True, "gaps": [], "unread": []}


def _management(name="management", **extra_fields):
    fields = [{"Field": "eventCategory", "Equals": ["Management"]}]
    fields += [{"Field": key, **value} for key, value in extra_fields.items()]
    return {"Name": name, "FieldSelectors": fields}


def _data(types, **extra_fields):
    fields = [
        {"Field": "eventCategory", "Equals": ["Data"]},
        {"Field": "resources.type", "Equals": list(types)},
    ]
    fields += [{"Field": key, **value} for key, value in extra_fields.items()]
    return {"Name": "data", "FieldSelectors": fields}


class TestBR06SelectorValues:
    """AIR-BDR-KB-06 and AIR-BDR-MDL-07: selectors are judged by every field."""

    @staticmethod
    def _run(
        trails,
        record=None,
        knowledge_bases=({"knowledgeBaseId": "kb-1"},),
        event_data_stores=({"EventDataStores": []},),
        store_details=None,
        remote_clients=None,
    ):
        """
        trails: {name: {"advanced": [...], "basic": [...], "error": code,
        "home": Region}}; a trail with a home is a single-Region trail there.
        event_data_stores: ListEventDataStores pages, or an exception to raise.
        store_details: {store ARN: GetEventDataStore response, or an exception};
        an ARN left out answers ENABLED with no selectors.
        remote_clients: {Region: client} answering for another assessed Region.
        """

        def name_of(arn):
            return arn.rsplit("/", 1)[-1]

        def selectors(TrailName):
            trail = trails[name_of(TrailName)]
            if trail.get("error"):
                raise ClientError(
                    {"Error": {"Code": trail["error"], "Message": "x"}},
                    "GetEventSelectors",
                )
            return {
                "EventSelectors": trail.get("basic", []),
                "AdvancedEventSelectors": trail.get("advanced", []),
            }

        client = MagicMock()
        client.list_trails.return_value = {
            "Trails": [
                {"TrailARN": f"arn:aws:cloudtrail:us-east-1:123:trail/{n}", "Name": n}
                for n in trails
            ]
        }
        client.get_trail.side_effect = lambda Name: {
            "Trail": (
                {
                    "IsMultiRegionTrail": False,
                    "HomeRegion": trails[name_of(Name)]["home"],
                }
                if trails[name_of(Name)].get("home")
                else {"IsMultiRegionTrail": True}
            )
        }
        client.get_trail_status.side_effect = lambda Name: {"IsLogging": True}
        client.get_event_selectors.side_effect = selectors
        client.list_knowledge_bases.return_value = {
            "knowledgeBaseSummaries": list(knowledge_bases)
        }
        client.list_data_sources.return_value = {"dataSourceSummaries": []}
        client.list_event_data_stores.side_effect = (
            event_data_stores
            if isinstance(event_data_stores, Exception)
            else list(event_data_stores)
        )

        def get_store(EventDataStore):
            answer = (store_details or {}).get(
                EventDataStore, {"Status": "ENABLED", "AdvancedEventSelectors": []}
            )
            if isinstance(answer, Exception):
                raise answer
            return {"EventDataStoreArn": EventDataStore, **answer}

        client.get_event_data_store.side_effect = get_store
        TestBR06SelectorValues.store_client = client
        remote_clients = remote_clients or {}
        with (
            patch(
                "boto3.client",
                side_effect=lambda *args, region_name=None, **kwargs: (
                    remote_clients.get(region_name, client)
                ),
            ),
            patch("bedrock_app.detect_bedrock_regional_footprint", return_value=True),
            patch(
                "bedrock_app._invocation_record_state",
                create=True,
                return_value=record or COMPLETE_RECORD,
            ),
        ):
            findings = extract_csv_data(
                bedrock_app.check_bedrock_cloudtrail_logging(region="us-east-1")
            )
        for finding in findings:
            assert_finding_schema(finding)
        return {f["Finding"]: f for f in findings}

