    # Round 2: who may change a prompt or publish a version of it.

    @staticmethod
    def _grant(actions, resources, effect="Allow"):
        return {
            "policy_name": "prompts",
            "document": {
                "Statement": [
                    {"Effect": effect, "Action": actions, "Resource": resources}
                ]
            },
        }

    def _scope_rows(self, permission_cache):
        return self._rows(
            self._run(self._client(), permission_cache=permission_cache),
            bedrock_app.PROMPT_WRITE_SCOPE_FINDING,
        )

    def test_br07_update_prompt_on_every_prompt_fails(self):
        rows = self._scope_rows(
            {
                "cache_schema_version": 2,
                "role_permissions": {
                    "editor": {
                        "inline_policies": [
                            self._grant(
                                "bedrock:UpdatePrompt",
                                "arn:aws:bedrock:us-east-1:123456789012:prompt/*",
                            )
                        ]
                    }
                },
            }
        )

        assert [row["Status"] for row in rows] == ["Failed"]
        assert "role 'editor'" in rows[0]["Finding_Details"]

    def test_br07_one_wide_editor_fails_beside_one_scoped_editor(self):
        rows = self._scope_rows(
            {
                "cache_schema_version": 2,
                "role_permissions": {
                    "scoped": {
                        "inline_policies": [
                            self._grant(
                                ["bedrock:UpdatePrompt", "bedrock:CreatePromptVersion"],
                                self._PROMPT_ARN,
                            )
                        ]
                    },
                    "wide": {
                        "attached_policies": [
                            self._grant("bedrock:CreatePromptVersion", "*")
                        ]
                    },
                },
            }
        )

        assert [row["Status"] for row in rows] == ["Failed"]
        assert "role 'wide'" in rows[0]["Finding_Details"]
        assert "role 'scoped'" not in rows[0]["Finding_Details"]

    def test_br07_prefix_wildcard_prompt_arn_is_not_scoped(self):
        rows = self._scope_rows(
            {
                "cache_schema_version": 2,
                "role_permissions": {
                    "editor": {
                        "inline_policies": [
                            self._grant(
                                "bedrock:UpdatePrompt",
                                "arn:aws:bedrock:us-east-1:123456789012:prompt/prod-*",
                            )
                        ]
                    }
                },
            }
        )

        assert [row["Status"] for row in rows] == ["Failed"]
        assert "prompt/prod-*" in rows[0]["Finding_Details"]

    def test_br07_group_policy_grant_reaches_the_scope_leg(self):
        rows = self._scope_rows(
            {
                "cache_schema_version": 2,
                "role_permissions": {},
                "user_permissions": {
                    "alice": {
                        "group_policies": [
                            {"group": "editors", **self._grant("bedrock:*", "*")}
                        ]
                    }
                },
            }
        )

        assert [row["Status"] for row in rows] == ["Failed"]
        assert "user 'alice'" in rows[0]["Finding_Details"]

    def test_br07_scoped_editors_pass_and_errored_principal_holds_it_back(self):
        cache = {
            "cache_schema_version": 2,
            "role_permissions": {
                "scoped": {
                    "inline_policies": [
                        self._grant("bedrock:UpdatePrompt", self._PROMPT_ARN)
                    ]
                }
            },
        }
        assert [row["Status"] for row in self._scope_rows(cache)] == ["Passed"]

        cache["principal_errors"] = [
            {"type": "role", "name": "hidden", "stage": "inline_policy", "error": "x"}
        ]
        assert [row["Status"] for row in self._scope_rows(cache)] == ["N/A", "N/A"]

    def test_br07_no_permission_cache_is_not_passed(self):
        rows = self._scope_rows(None)

        assert [row["Status"] for row in rows] == ["N/A"]

    def test_br07_delete_prompt_on_every_prompt_fails(self):
        rows = self._scope_rows(
            {
                "cache_schema_version": 2,
                "role_permissions": {
                    "scoped": {
                        "inline_policies": [
                            self._grant("bedrock:DeletePrompt", self._PROMPT_ARN)
                        ]
                    },
                    "wide": {
                        "inline_policies": [
                            self._grant(
                                "bedrock:DeletePrompt",
                                "arn:aws:bedrock:us-east-1:123456789012:prompt/*",
                            )
                        ]
                    },
                },
            }
        )

        assert [row["Status"] for row in rows] == ["Failed"]
        assert "role 'wide' (bedrock:deleteprompt on" in rows[0]["Finding_Details"]
        assert "role 'scoped'" not in rows[0]["Finding_Details"]

    def test_br07_a_role_that_renders_and_changes_prompts_fails(self):
        cache = {
            "cache_schema_version": 2,
            "role_permissions": {
                "runtime": {
                    "inline_policies": [
                        self._grant("bedrock:RenderPrompt", self._PROMPT_ARN)
                    ]
                },
                "editor": {
                    "inline_policies": [
                        self._grant("bedrock:UpdatePrompt", self._PROMPT_ARN)
                    ]
                },
            },
        }
        assert [row["Status"] for row in self._scope_rows(cache)] == ["Passed"]

        cache["role_permissions"]["runtime"]["inline_policies"].append(
            self._grant("bedrock:CreatePromptVersion", self._PROMPT_ARN)
        )
        rows = self._scope_rows(cache)

        assert [row["Status"] for row in rows] == ["Failed"]
        assert (
            "1 role(s) or user(s) may both render prompts (bedrock:RenderPrompt) "
            "and change them: role 'runtime'." in rows[0]["Finding_Details"]
        )
        assert "role 'editor'" not in rows[0]["Finding_Details"]

    # MDL-08: bedrock:CreatePrompt has no resource type, so its holders were
    # neither read nor reported.
    def test_br07_prompt_creators_are_named_and_a_denied_one_is_not(self):
        cache = {
            "cache_schema_version": 2,
            "role_permissions": {
                "release": {
                    "inline_policies": [self._grant("bedrock:CreatePrompt", "*")]
                },
                "builder": {
                    "attached_policies": [self._grant("bedrock:CreatePromp?", "*")]
                },
                "blocked": {
                    "inline_policies": [
                        self._grant("bedrock:CreatePrompt", "*"),
                        self._grant("bedrock:CreatePrompt", "*", effect="Deny"),
                    ]
                },
            },
        }
        rows = self._scope_rows(cache)

        assert [row["Status"] for row in rows] == ["Passed"]
        details = rows[0]["Finding_Details"]
        assert (
            "2 role(s) or user(s) may create prompts with bedrock:CreatePrompt, "
            "which has no resource type, so no Resource ARN bounds it: "
            "role 'release'; role 'builder'." in details
        )
        assert "role 'blocked'" not in details
        assert "None of them may also call bedrock:RenderPrompt." in details

    def test_br07_no_prompt_creator_is_said_so(self):
        rows = self._scope_rows(
            {
                "cache_schema_version": 2,
                "role_permissions": {
                    "editor": {
                        "inline_policies": [
                            self._grant("bedrock:UpdatePrompt", self._PROMPT_ARN)
                        ]
                    }
                },
            }
        )

        assert [row["Status"] for row in rows] == ["Passed"]
        assert (
            "No role or user may call bedrock:CreatePrompt."
            in rows[0]["Finding_Details"]
        )

    @pytest.mark.parametrize("create", ["bedrock:CreatePrompt", "bedrock:CreatePromp?"])
    def test_br07_a_role_that_renders_and_creates_prompts_fails(self, create):
        rows = self._scope_rows(
            {
                "cache_schema_version": 2,
                "role_permissions": {
                    "release": {
                        "inline_policies": [self._grant("bedrock:CreatePrompt", "*")]
                    },
                    "runtime": {
                        "inline_policies": [
                            self._grant("bedrock:RenderPrompt", self._PROMPT_ARN),
                            self._grant(create, "*"),
                        ]
                    },
                },
            }
        )

        assert [row["Status"] for row in rows] == ["Failed"]
        details = rows[0]["Finding_Details"]
        assert (
            "1 role(s) or user(s) may both render prompts (bedrock:RenderPrompt) "
            "and create them (bedrock:CreatePrompt): role 'runtime'." in details
        )


