        check = bedrock_app.check_bedrock_agent_roles
        mock_agent = MagicMock()
        paginator = MagicMock()
        mock_client.return_value = mock_agent
        mock_agent.get_paginator.return_value = paginator
        paginator.paginate.return_value = [{"agentSummaries": []}]
