# ===================================================================
# BR-27: check_bedrock_guardrail_contextual_grounding
# ===================================================================
class TestKnowledgeBaseScreening:
    """
    AIR-BDR-KB-05 and AIR-BDR-KB-08: BR-34 and BR-26 fail a knowledge base
    that ingests a data source with no screening step and is reached through
    no guardrail that screens it. Neither leg ever passes a knowledge base.
    """

    REGION = "us-east-1"
    PROMPT_ATTACK = {
        "contentPolicy": {
            "filters": [
                {
                    "type": "PROMPT_ATTACK",
                    "inputEnabled": True,
                    "inputAction": "BLOCK",
                    "inputStrength": "HIGH",
                }
            ],
            "tier": {"tierName": "STANDARD"},
        }
    }
    DETECT_ONLY = {
        "contentPolicy": {
            "filters": [
                {
                    "type": "PROMPT_ATTACK",
                    "inputEnabled": True,
                    "inputAction": "NONE",
                    "inputStrength": "HIGH",
                }
            ],
            "tier": {"tierName": "STANDARD"},
        }
    }
    MASKS_PII = {
        "sensitiveInformationPolicy": {
            "piiEntities": [{"type": "EMAIL", "action": "ANONYMIZE"}]
        }
    }
    REGEX_ONLY = {
        "sensitiveInformationPolicy": {
            "regexes": [{"name": "k", "pattern": "k", "action": "BLOCK"}]
        }
    }
    MASKS_CREDENTIALS = {
        "sensitiveInformationPolicy": {
            "piiEntities": [
                {"type": t, "inputAction": "BLOCK", "outputAction": "ANONYMIZE"}
                for t in ("AWS_ACCESS_KEY", "AWS_SECRET_KEY", "PASSWORD", "EMAIL")
            ],
            "regexes": [{"name": "k", "pattern": "k", "outputAction": "BLOCK"}],
        }
    }
    REDACT_ALL = {
        "JobName": "redact-docs",
        "JobStatus": "COMPLETED",
        "Mode": "ONLY_REDACTION",
        "OutputDataConfig": {"S3Uri": "s3://docs/redacted/"},
        "RedactionConfig": {
            "PiiEntityTypes": ["ALL"],
            "MaskMode": "REPLACE_WITH_PII_ENTITY_TYPE",
        },
        "EndTime": "2026-09-01T00:00:00Z",
    }

    @staticmethod
    def _source(name, kind="S3", lambdas=(), bucket="docs", prefixes=(), kb="kb"):
        return {
            "knowledge_base_id": kb,
            "data_source_id": name,
            "label": f"data source '{name}'",
            "type": kind,
            "transformations": list(lambdas),
            "bucket": bucket,
            "prefixes": list(prefixes),
        }

    @staticmethod
    def _front(surface, guardrail="gr-1", version="1"):
        return {
            "surface": surface,
            "guardrail": {
                "identifier": guardrail,
                "region": "us-east-1",
                "version": version,
            }
            if guardrail
            else None,
        }

    @staticmethod
    def _kb(name, sources, fronts=(), errors=()):
        return {
            "id": name,
            "label": f"knowledge base '{name}'",
            "sources": sources,
            "fronts": list(fronts),
            "errors": list(errors),
        }

    @staticmethod
    def _inventory(kbs, details=None, errors=(), enforced=(), enforced_errors=()):
        return {
            "knowledge_bases": kbs,
            "errors": list(errors),
            "enforced": list(enforced),
            "enforced_errors": list(enforced_errors),
            "details": {
                key: {"detail": detail, "error": "" if detail else "AccessDenied"}
                for key, detail in (details or {}).items()
            },
            "list_error": "",
        }

    def _br34(self, inventory):
        result = bedrock_app.check_bedrock_guardrail_prompt_attack_filter(
            region=self.REGION,
            guardrail_inventory={"items": [], "errors": [], "list_error": None},
            attachment_inventory={"attachments": [], "versions": {}, "errors": []},
            knowledge_base_inventory=inventory,
        )
        return [
            f
            for f in extract_csv_data(result)
            if f["Finding"] == "Knowledge Base Ingestion Prompt Attack Screening"
        ]

    def _br26(
        self,
        inventory,
        jobs=None,
        jobs_error=None,
        ingestions=None,
        objects=None,
        glue_jobs=(),
        glue_jobs_error=None,
        glue_runs=None,
        glue_tables=None,
    ):
        """
        ``glue_runs`` maps a Glue job name to its (JobRunState, CompletedOn)
        runs, newest first, or to an exception; ``glue_tables`` maps
        (database, table) to an S3 location or an exception.
        """
        client = MagicMock()
        client.list_guardrails.return_value = {"guardrails": []}
        ingestions = ingestions or {}
        objects = objects or {}
        glue_runs = glue_runs or {}
        glue_tables = glue_tables or {}
        self.listed_prefixes = []

        def get_jobs():
            if glue_jobs_error:
                raise glue_jobs_error
            yield {"Jobs": list(glue_jobs)}

        def get_job_runs(JobName):
            # One run per page, so a newer run on a later page is still read.
            runs = glue_runs.get(JobName, [])
            if isinstance(runs, Exception):
                raise runs
            for state, completed in runs:
                yield {"JobRuns": [{"JobRunState": state, "CompletedOn": completed}]}

        def get_table(DatabaseName, Name):
            location = glue_tables[(DatabaseName, Name)]
            if isinstance(location, Exception):
                raise location
            return {"Table": {"StorageDescriptor": {"Location": location}}}

        client.get_table.side_effect = get_table

        def list_objects(Bucket, Prefix):
            self.listed_prefixes.append((Bucket, Prefix))
            pages = objects.get((Bucket, Prefix), [])
            if isinstance(pages, Exception):
                raise pages
            for page in pages:
                yield {"Contents": [{"Key": k, "LastModified": m} for k, m in page]}

        def get_paginator(name):
            paginator = MagicMock()
            if name == "list_objects_v2":
                paginator.paginate.side_effect = list_objects
            if name == "get_jobs":
                paginator.paginate.side_effect = get_jobs
            if name == "get_job_runs":
                paginator.paginate.side_effect = get_job_runs
            return paginator

        client.get_paginator.side_effect = get_paginator

        def list_ingestion_jobs(knowledgeBaseId, dataSourceId, **_):
            started = ingestions.get(dataSourceId, [])
            if isinstance(started, Exception):
                raise started
            return {"ingestionJobSummaries": [{"startedAt": t} for t in started]}

        client.list_ingestion_jobs.side_effect = list_ingestion_jobs
        if jobs_error:
            client.list_pii_entities_detection_jobs.side_effect = jobs_error
        else:
            client.list_pii_entities_detection_jobs.return_value = {
                "PiiEntitiesDetectionJobPropertiesList": jobs or []
            }
        with patch("bedrock_app.boto3.client", return_value=client):
            result = bedrock_app.check_bedrock_guardrail_pii_filters(
                region=self.REGION,
                attachment_inventory={"attachments": [], "versions": {}, "errors": []},
                knowledge_base_inventory=inventory,
            )
        return [
            f
            for f in extract_csv_data(result)
            if f["Finding"] == "Knowledge Base PII Redaction Before Model"
        ]

