        """51 data sources over two knowledge bases: all 51 buckets are read.

        Every bucket enforces TLS, so the whole population passes. The walk
        used to stop at 50 and withhold the pass.
        """
        data_sources = {
            "kb-1": [
                {"dataSourceId": f"ds-{i}", "name": f"docs-{i}"} for i in range(30)
            ],
            "kb-2": [
                {"dataSourceId": f"ds-{i}", "name": f"docs-{i}"} for i in range(30, 51)
            ],
        }
        detail = {
            f"ds-{i}": self._s3_source(f"ds-{i}", f"docs-{i}", f"bucket-{i}")
            for i in range(51)
        }
        findings = self._run(
            knowledge_bases=[
                {"knowledgeBaseId": "kb-1", "name": "support-kb"},
                {"knowledgeBaseId": "kb-2", "name": "hr-kb"},
            ],
            data_sources=data_sources,
            data_source_detail=detail,
            bucket_policies={
                f"bucket-{i}": _bucket_policy(_tls_deny_statement([f"bucket-{i}"]))
                for i in range(51)
            },
        )

        assert [f["Status"] for f in findings] == ["Passed"]
        assert "51 of 51 Bedrock data path bucket(s)" in findings[0]["Finding_Details"]
        assert "read cap" not in findings[0]["Finding_Details"]
        assert self.last_s3_client.get_bucket_policy.call_count == 51
        for finding in findings:
            assert_finding_schema(finding)

