    INSTANCE = "arn:aws:sso:::instance/ssoins-1"
    PS_WRITE = "arn:aws:sso:::permissionSet/ssoins-1/ps-write"
    PS_READ = "arn:aws:sso:::permissionSet/ssoins-1/ps-read"
    PS_LATE = "arn:aws:sso:::permissionSet/ssoins-1/ps-late"

    @staticmethod
    def _policy(*actions):
        return json.dumps(
            {
                "Version": "2012-10-17",
                "Statement": [
                    {"Effect": "Allow", "Action": list(actions), "Resource": "*"}
                ],
            }
        )

    def _run_sets(self, **kwargs):
        return self._run(
            _ai_user_cache(),
            login={"alice": "yes"},
            devices={"alice": [{"SerialNumber": "s"}]},
            instances=[{"Instances": [{"InstanceArn": self.INSTANCE}]}],
            **kwargs,
        )

    def test_br51_names_the_permission_set_granting_ai_writes_beside_a_read_one(
        self,
    ):
        _, rows = self._run_sets(
            permission_sets={
                self.INSTANCE: {
                    None: {
                        "PermissionSets": [self.PS_READ, self.PS_WRITE],
                        "NextToken": "p2",
                    },
                    "p2": {"PermissionSets": [self.PS_LATE]},
                }
            },
            inline={
                self.PS_READ: self._policy("bedrock:ListFoundationModels"),
                self.PS_WRITE: self._policy("bedrock:CreateGuardrail"),
                self.PS_LATE: self._policy("sagemaker:CreateEndpoint"),
            },
        )
        assert [r["Status"] for r in rows] == ["N/A", "Failed", "Failed"]
        assert self.PS_WRITE in rows[1]["Finding_Details"]
        assert self.PS_LATE in rows[2]["Finding_Details"]
        details = rows[0]["Finding_Details"]
        assert (
            "2 permission set(s) grant AI writes in their inline or AWS managed "
            "policies" in details
        )
        assert f"{self.PS_WRITE} (bedrock)" in details
        assert f"{self.PS_LATE} (sagemaker)" in details
        assert self.PS_READ not in details
        assert "Partial, ceiling reached" in details
        self.iam.list_permission_sets.assert_has_calls(
            [
                call(InstanceArn=self.INSTANCE, MaxResults=100),
                call(InstanceArn=self.INSTANCE, MaxResults=100, NextToken="p2"),
            ]
        )

    def test_br51_no_granting_permission_set_still_is_not_passed(self):
        _, rows = self._run_sets(
            permission_sets={self.INSTANCE: [self.PS_READ]},
            inline={self.PS_READ: self._policy("bedrock:Get*")},
        )
        assert [r["Status"] for r in rows] == ["N/A"]
        assert (
            "No permission set inline or AWS managed policy that was read grants "
            "AI writes." in rows[0]["Finding_Details"]
        )

    def test_br51_an_unread_inline_policy_is_named_not_read_as_clean(self):
        _, rows = self._run_sets(
            permission_sets={self.INSTANCE: [self.PS_READ, self.PS_WRITE]},
            inline={
                self.PS_READ: self._policy("bedrock:Get*"),
                self.PS_WRITE: _make_client_error("AccessDeniedException"),
            },
        )
        details = rows[0]["Finding_Details"]
        assert (
            f"sso:GetInlinePolicyForPermissionSet on {self.PS_WRITE} "
            "(AccessDeniedException)" in details
        )

    @staticmethod
    def _tag_deny(
        operator="StringNotEquals",
        key="aws:PrincipalTag/authn",
        value="mfa",
        actions=("bedrock:*", "sagemaker:*", "bedrock-agentcore:*"),
        **statement,
    ):
        body = {
            "Effect": "Deny",
            "Action": list(actions),
            "Resource": "*",
            "Condition": {operator: {key: value}},
        }
        body.update(statement)
        return body

    @staticmethod
    def _grant_with(*denies, actions=("bedrock:CreateGuardrail",)):
        return json.dumps(
            {
                "Version": "2012-10-17",
                "Statement": [
                    {"Effect": "Allow", "Action": list(actions), "Resource": "*"},
                    *denies,
                ],
            }
        )

    def test_br51_permission_set_without_a_principal_tag_deny_fails(self):
        _, rows = self._run_sets(
            permission_sets={self.INSTANCE: [self.PS_WRITE]},
            inline={self.PS_WRITE: self._grant_with()},
        )
        assert [r["Status"] for r in rows] == ["N/A", "Failed"]
        failed = rows[1]
        assert failed["Check_ID"] == "BR-51"
        assert failed["Severity"] == "High"
        assert (
            f"permission set {self.PS_WRITE} grants AI writes (bedrock) in its "
            "inline policy, and no policy of the permission set carries a Deny "
            "keyed on an aws:PrincipalTag authentication tag over bedrock"
            in failed["Finding_Details"]
        )
        assert "not read" not in failed["Finding_Details"].replace(
            bedrock_app.AI_USER_MFA_SCOPE_NOTE, ""
        )
        assert "references no customer managed policy" in failed["Finding_Details"]
        assert "0 of them carry" in rows[0]["Finding_Details"]

    def test_br51_only_the_second_permission_set_without_the_deny_fails(self):
        _, rows = self._run_sets(
            permission_sets={
                self.INSTANCE: {
                    None: {"PermissionSets": [self.PS_READ], "NextToken": "p2"},
                    "p2": {"PermissionSets": [self.PS_WRITE]},
                }
            },
            inline={
                self.PS_READ: self._grant_with(self._tag_deny()),
                self.PS_WRITE: self._grant_with(),
            },
        )
        assert [r["Status"] for r in rows] == ["N/A", "Failed"]
        assert self.PS_WRITE in rows[1]["Finding_Details"]
        assert self.PS_READ not in rows[1]["Finding_Details"]
        details = rows[0]["Finding_Details"]
        assert "1 of them carry" in details
        assert (
            f"{self.PS_READ} (bedrock): StringNotEquals aws:PrincipalTag/authn mfa"
            in details
        )
        assert "1 do not, and each is failed in its own row." in details

    def test_br51_every_permission_set_carrying_the_deny_stays_at_the_ceiling(self):
        _, rows = self._run_sets(
            permission_sets={self.INSTANCE: [self.PS_WRITE, self.PS_LATE]},
            inline={
                self.PS_WRITE: self._grant_with(self._tag_deny()),
                self.PS_LATE: self._grant_with(
                    self._tag_deny(
                        operator="StringNotLike",
                        actions=(),
                        NotAction=["bedrock:Get*", "bedrock:List*"],
                    )
                ),
            },
        )
        assert [r["Status"] for r in rows] == ["N/A"]
        details = rows[0]["Finding_Details"]
        assert "2 of them carry" in details
        assert "Partial, ceiling reached" in details
        # Stricter since DescribeInstanceAccessControlAttributeConfiguration is
        # read: the row used to say only that it was not read, and now says
        # where each guarded set's tag comes from.
        assert (
            "aws:PrincipalTag/authn is not an attribute for access control on the "
            "instance (configuration status ENABLED), so any value comes only "
            "from the identity provider's SAML assertion, which is not read"
        ) in details
        assert "are not read." not in details

    def test_br51_a_configured_attribute_names_its_source_per_permission_set(self):
        _, rows = self._run_sets(
            permission_sets={self.INSTANCE: [self.PS_WRITE, self.PS_LATE]},
            inline={
                self.PS_WRITE: self._grant_with(self._tag_deny()),
                self.PS_LATE: self._grant_with(
                    self._tag_deny(key="aws:PrincipalTag/Level")
                ),
            },
            abac={
                "Status": "ENABLED",
                "InstanceAccessControlAttributeConfiguration": {
                    "AccessControlAttributes": [
                        {
                            "Key": "AuthN",
                            "Value": {"Source": ["${path:enterprise.amr}"]},
                        }
                    ]
                },
            },
        )
        assert [r["Status"] for r in rows] == ["N/A"]
        details = rows[0]["Finding_Details"]
        assert (
            f"{self.PS_WRITE} (bedrock): StringNotEquals aws:PrincipalTag/authn mfa "
            "(aws:PrincipalTag/authn is the instance's attribute for access control "
            "set from ${path:enterprise.amr} (configuration status ENABLED); whether "
            "that source reflects MFA is not judged)"
        ) in details
        assert (
            f"{self.PS_LATE} (bedrock): StringNotEquals aws:PrincipalTag/Level mfa "
            "(aws:PrincipalTag/Level is not an attribute for access control"
        ) in details
        self.iam.describe_instance_access_control_attribute_configuration.assert_called_once_with(
            InstanceArn=self.INSTANCE
        )

    def test_br51_an_unread_attribute_configuration_is_named(self):
        _, rows = self._run_sets(
            permission_sets={self.INSTANCE: [self.PS_WRITE]},
            inline={self.PS_WRITE: self._grant_with(self._tag_deny())},
            abac=_make_client_error("AccessDeniedException"),
        )
        assert [r["Status"] for r in rows] == ["N/A"]
        details = rows[0]["Finding_Details"]
        assert (
            "where aws:PrincipalTag/authn comes from was not read, because "
            "sso:DescribeInstanceAccessControlAttributeConfiguration on "
            f"{self.INSTANCE} (AccessDenied"
        ) in details
        assert (
            "These reads failed: sso:DescribeInstanceAccessControlAttributeConfiguration"
            in details
        )

    def test_br51_principal_tag_deny_forms_that_do_not_fire_are_not_credited(self):
        forms = {
            "set_ifexists": self._tag_deny(
                operator="ForAnyValue:StringNotEqualsIfExists"
            ),
            "set": self._tag_deny(operator="ForAnyValue:StringNotEquals"),
            "equals": self._tag_deny(operator="StringEquals"),
            "resource": self._tag_deny(Resource="arn:aws:bedrock:*:*:agent/*"),
            "other_key": self._tag_deny(key="aws:RequestTag/authn"),
            "bare_prefix": self._tag_deny(key="aws:PrincipalTag/"),
            "second_key": self._tag_deny(
                Condition={
                    "StringNotEquals": {
                        "aws:PrincipalTag/authn": "mfa",
                        "aws:PrincipalAccount": "111122223333",
                    }
                }
            ),
            "allow": self._tag_deny(Effect="Allow"),
        }
        sets = {
            f"arn:aws:sso:::permissionSet/ssoins-1/ps-{name}": self._grant_with(deny)
            for name, deny in forms.items()
        }
        _, rows = self._run_sets(
            permission_sets={self.INSTANCE: list(sets)}, inline=sets
        )
        failed = [r["Finding_Details"] for r in rows if r["Status"] == "Failed"]
        assert len(failed) == len(forms)
        for arn in sets:
            assert sum(arn + " " in text for text in failed) == 1, arn

    @pytest.mark.parametrize(
        "operator",
        [
            "StringNotEqualsIfExists",
            "StringNotEqualsIgnoreCaseIfExists",
            "StringNotLikeIfExists",
            "ForAllValues:StringNotEquals",
        ],
    )
    def test_br51_a_principal_tag_deny_true_on_an_absent_tag_is_credited(
        self, operator
    ):
        """An IfExists or ForAllValues: negated test is true on an untagged
        session, so it denies it as the plain form does; the set without the
        Deny beside it still fails."""
        _, rows = self._run_sets(
            permission_sets={self.INSTANCE: [self.PS_WRITE, self.PS_LATE]},
            inline={
                self.PS_WRITE: self._grant_with(self._tag_deny(operator=operator)),
                self.PS_LATE: self._grant_with(),
            },
        )
        assert [r["Status"] for r in rows] == ["N/A", "Failed"]
        assert self.PS_LATE in rows[1]["Finding_Details"]
        assert self.PS_WRITE not in rows[1]["Finding_Details"]
        assert "1 of them carry" in rows[0]["Finding_Details"]
        assert (
            f"{self.PS_WRITE} (bedrock): {operator} aws:PrincipalTag/authn mfa"
            in rows[0]["Finding_Details"]
        )

    def test_br51_a_scp_tag_deny_holds_a_permission_set_in_this_account_only(self):
        _, rows = self._run_sets(
            permission_sets={self.INSTANCE: [self.PS_WRITE, self.PS_LATE]},
            inline={
                self.PS_WRITE: self._grant_with(),
                self.PS_LATE: self._grant_with(actions=("sagemaker:CreateEndpoint",)),
            },
            scp_inventory=TestBR51AIUserConsoleMFA._scps(
                self._tag_deny(actions=("bedrock:*",))
            ),
        )
        assert [r["Status"] for r in rows] == ["N/A", "N/A", "Failed"]
        held = rows[1]["Finding_Details"]
        assert self.PS_WRITE in held
        assert (
            "The service control policies attached to this account deny them "
            "(StringNotEquals aws:PrincipalTag/authn mfa in service control policy "
            "'RequireMfa'), which holds the set's sessions in this account only" in held
        )
        failed = rows[2]["Finding_Details"]
        assert self.PS_LATE in failed
        assert (
            "nor does one in the 1 service control policy attached to this account "
            "over sagemaker, so a session that did not complete MFA is not denied"
            in failed
        )

