class TestBR53OwnerTagSweep:
    """AIR-FND-GOV-02: SageMaker and AgentCore resources the Bedrock lists miss."""

    SM_OWNED = "arn:aws:sagemaker:us-east-1:123456789012:endpoint/owned"
    SM_TBD = "arn:aws:sagemaker:us-east-1:123456789012:endpoint/tbd"
    SM_LATE = "arn:aws:sagemaker:us-east-1:123456789012:model/late"
    SM_TRAINING = "arn:aws:sagemaker:us-east-1:123456789012:training-job/never"
    AC_BARE = "arn:aws:bedrock-agentcore:us-east-1:123456789012:runtime/rt-1"

    LIST_KEYS = {
        "list_endpoints": "Endpoints",
        "list_models": "Models",
        "list_notebook_instances": "NotebookInstances",
        "list_memories": "memories",
        "list_gateways": "items",
        "list_browsers": "browserSummaries",
        "list_training_jobs": "TrainingJobSummaries",
        "list_domains": "Domains",
        "list_code_interpreters": "codeInterpreterSummaries",
        "list_inference_components": "InferenceComponents",
        "list_pipelines": "PipelineSummaries",
        "list_processing_jobs": "ProcessingJobSummaries",
        "list_transform_jobs": "TransformJobSummaries",
        "list_workload_identities": "workloadIdentities",
        "list_clusters": "ClusterSummaries",
        "list_harnesses": "harnesses",
    }

    def _run(self, pages, errors=None, runtimes=None, lists=None, setup=None):
        """``setup`` receives the shared client mock before the check runs."""
        errors = errors or {}
        tagging = MagicMock()
        if isinstance(runtimes, Exception):
            tagging.list_agent_runtimes.side_effect = runtimes
        else:
            tagging.list_agent_runtimes.side_effect = list(
                runtimes or [{"agentRuntimes": []}]
            )
        lists = lists or {}
        for operation, key in self.LIST_KEYS.items():
            value = lists.get(operation, [])
            method = getattr(tagging, operation)
            if isinstance(value, Exception) or callable(value):
                method.side_effect = value
            else:
                method.return_value = {key: value}

        def get_resources(**kwargs):
            (type_filter,) = kwargs["ResourceTypeFilters"]
            if type_filter in errors:
                raise errors[type_filter]
            service_pages = pages.get(type_filter, [[]])
            index = int(kwargs.get("PaginationToken") or 0)
            response = {"ResourceTagMappingList": service_pages[index]}
            response["PaginationToken"] = (
                str(index + 1) if index + 1 < len(service_pages) else ""
            )
            return response

        tagging.get_resources.side_effect = get_resources
        if setup:
            setup(tagging)
        with patch("boto3.client", return_value=tagging):
            result = bedrock_app.check_ai_resource_owner_tag_sweep(region="us-east-1")
        rows = extract_csv_data(result)
        for row in rows:
            assert_finding_schema(row)
            assert row["Check_ID"] == "BR-53"
            assert row["Finding"] == "AI Resource Owner Tag Outside Bedrock"
        return result, rows, tagging

    def test_one_unowned_resource_per_service_fails_beside_an_owned_one(self):
        result, rows, tagging = self._run(
            {
                "sagemaker": [
                    [
                        {
                            "ResourceARN": self.SM_OWNED,
                            "Tags": [{"Key": "Owner", "Value": "ml-platform"}],
                        },
                        {
                            "ResourceARN": self.SM_TBD,
                            "Tags": [{"Key": "owner", "Value": "TBD"}],
                        },
                    ]
                ],
                "bedrock-agentcore": [[{"ResourceARN": self.AC_BARE, "Tags": []}]],
            }
        )
        assert [r["Status"] for r in rows] == ["Failed", "Failed", "N/A"]
        assert f"SageMaker resource {self.SM_TBD}" in rows[0]["Finding_Details"]
        assert "placeholder 'TBD'" in rows[0]["Finding_Details"]
        assert f"AgentCore resource {self.AC_BARE}" in rows[1]["Finding_Details"]
        assert "no tags returned" in rows[1]["Finding_Details"]
        assert "1 of the 3 SageMaker and AgentCore" in rows[2]["Finding_Details"]
        assert result["status"] == "WARN"
        assert [
            c.kwargs["ResourceTypeFilters"]
            for c in tagging.get_resources.call_args_list
        ] == [["sagemaker"], ["bedrock-agentcore"]]

    def test_every_returned_resource_owned_passes_and_names_the_types_left_unlisted(
        self,
    ):
        """GOV-02: changed from N/A under the round-6 direction. Every list read
        and filter was read and nothing lacks an owner, so the row passes; the
        types only GetResources reaches are still named."""
        result, rows, _ = self._run(
            {
                "sagemaker": [
                    [
                        {
                            "ResourceARN": self.SM_OWNED,
                            "Tags": [{"Key": "Owner", "Value": "ml-platform"}],
                        }
                    ]
                ]
            }
        )
        assert [r["Status"] for r in rows] == ["Passed"]
        assert result["status"] == "PASS"
        details = rows[0]["Finding_Details"]
        assert "1 of the 1 SageMaker and AgentCore" in details
        assert "production resources are not told apart" in details
        assert "This is not a verdict" not in details
        assert "a resource never tagged is not listed" in details
        assert "APIReference/API_GetResources.html)." in details
        assert (
            "SageMaker and AgentCore resource types other than endpoints, models, "
            "notebook instances, training jobs, domains, inference components, "
            "pipelines, processing jobs, transform jobs, HyperPod clusters, agent "
            "runtimes, memories, gateways, custom browsers, custom code "
            "interpreters, workload identities and harnesses are read only "
            "through GetResources" in details
        )
        assert "not granted" not in details
        assert "ceiling reached" not in details
        assert "bedrock-agentcore:ListAgentRuntimes" in details

