class TestBR55EnclaveKeyBinding:
    """BR-55: KMS keys declared enclave-bound must pin the image and leave no
    unattested decrypt path."""

    DIGEST = "a" * 96
    ROOT = {
        "Sid": "Enable IAM User Permissions",
        "Effect": "Allow",
        "Principal": {"AWS": "arn:aws:iam::123456789012:root"},
        "Action": "kms:*",
        "Resource": "*",
    }

    PCR3 = "kms:RecipientAttestation:PCR3"
    DEPLOYMENT_GAP = (
        "with no exact PCR3 (parent IAM role) or PCR4 (parent instance ID) value"
    )
    IMAGE_GAP = (
        "with no exact ImageSha384 or PCR0 (enclave image) or PCR8 (signing "
        "certificate) value"
    )

    def _enclave_allow(
        self, key="kms:RecipientAttestation:ImageSha384", deployment=True, **kwargs
    ):
        values = {key: self.DIGEST}
        if deployment and "NitroTPM" not in key:
            values[self.PCR3] = self.DIGEST
        statement = {
            "Sid": "EnclaveDecrypt",
            "Effect": "Allow",
            "Principal": {"AWS": "arn:aws:iam::123456789012:role/enclave"},
            "Action": ["kms:Decrypt", "kms:GenerateDataKey"],
            "Resource": "*",
            "Condition": kwargs.get("condition", {"StringEqualsIgnoreCase": values}),
        }
        return statement

    def _deployment_deny(self):
        return {
            "Sid": "DenyOtherParents",
            "Effect": "Deny",
            "Principal": "*",
            "Action": [
                "kms:Decrypt",
                "kms:DeriveSharedSecret",
                "kms:GenerateDataKey*",
                "kms:ReEncryptFrom",
            ],
            "Resource": "*",
            "Condition": {"StringNotEqualsIgnoreCase": {self.PCR3: self.DIGEST}},
        }

    def _image_deny(self):
        return dict(
            self._deployment_deny(),
            Sid="DenyOtherImages",
            Condition={
                "StringNotEqualsIgnoreCase": {
                    "kms:RecipientAttestation:ImageSha384": self.DIGEST
                }
            },
        )

    def test_br55_pcr3_only_pin_fails_beside_an_image_and_parent_pin(self):
        """AIR-FND-DAT-10: a parent pin with no image pin admits any image."""
        _, rows, _ = self._run(
            {
                "a-pcr3-only": [self._enclave_allow(key=self.PCR3, deployment=False)],
                "b-pcr4-only": [
                    self._enclave_allow(
                        key="kms:RecipientAttestation:PCR4", deployment=False
                    )
                ],
                "c-both": [self._enclave_allow()],
            }
        )
        assert [r["Status"] for r in rows] == ["Failed", "Failed", "Passed"]
        for row, key in zip(rows[:2], ("a-pcr3-only", "b-pcr4-only")):
            assert f"arn:k/{key}" in row["Finding_Details"]
            assert (
                "statement 'EnclaveDecrypt' releases kms:decrypt, kms:generatedatakey "
                f"{self.IMAGE_GAP}" in row["Finding_Details"]
            )
            assert self.DEPLOYMENT_GAP not in row["Finding_Details"]
        assert "arn:k/c-both (Nitro Enclave)" in rows[2]["Finding_Details"]
        assert "pcr3-only" not in rows[2]["Finding_Details"]

    def test_br55_pcr8_with_an_image_pin_binds_no_parent(self):
        """PCR8 names the signer, not the parent, so it is no deployment pin."""
        _, rows, _ = self._run(
            {
                "a-image-and-pcr8": [
                    self._enclave_allow(
                        condition={
                            "StringEqualsIgnoreCase": {
                                "kms:RecipientAttestation:ImageSha384": self.DIGEST,
                                "kms:RecipientAttestation:PCR8": self.DIGEST,
                            }
                        }
                    )
                ],
                "b-pcr8-and-pcr3": [
                    self._enclave_allow(key="kms:RecipientAttestation:PCR8")
                ],
            }
        )
        assert [r["Status"] for r in rows] == ["Failed", "Passed"]
        assert "arn:k/a-image-and-pcr8" in rows[0]["Finding_Details"]
        assert self.DEPLOYMENT_GAP in rows[0]["Finding_Details"]
        assert "arn:k/b-pcr8-and-pcr3 (Nitro Enclave)" in rows[1]["Finding_Details"]

    def _assert_root_closed_but_unbound(self, row):
        """The Deny closed the unattested root path; only the parent is open."""
        details = row["Finding_Details"]
        assert "to the account" not in details
        assert (
            f"statement 'Enable IAM User Permissions' releases kms:decrypt, "
            f"kms:derivesharedsecret, kms:generatedatakey, kms:generatedatakeypair, kms:reencryptfrom "
            f"{self.DEPLOYMENT_GAP}" in details
        )

    def _admin(self):
        return {
            "Sid": "Admin",
            "Effect": "Allow",
            "Principal": {"AWS": "arn:aws:iam::123456789012:role/admin"},
            "Action": ["kms:Describe*", "kms:Put*", "kms:ScheduleKeyDeletion"],
            "Resource": "*",
        }

    def _run(
        self,
        policies,
        key_manager=None,
        pages=None,
        policy_error=None,
        grants=None,
        grants_error=None,
        events=None,
        events_error=None,
    ):
        """events: {key ARN: [page of LookupEvents events, ...]}."""
        kms = MagicMock()

        def lookup_events(LookupAttributes, MaxResults, NextToken=None):
            (attribute,) = LookupAttributes
            assert attribute["AttributeKey"] == "ResourceName"
            arn = attribute["AttributeValue"]
            if events_error and arn in events_error:
                raise events_error[arn]
            pages_for_key = (events or {}).get(arn, [[]])
            index = int(NextToken or 0)
            response = {"Events": pages_for_key[index]}
            if index + 1 < len(pages_for_key):
                response["NextToken"] = str(index + 1)
            return response

        kms.lookup_events.side_effect = lookup_events

        def list_grants(KeyId, **kwargs):
            if grants_error and KeyId in grants_error:
                raise grants_error[KeyId]
            pages_for_key = (grants or {}).get(KeyId, [[]])
            index = int(kwargs.get("Marker") or 0)
            response = {"Grants": pages_for_key[index]}
            if index + 1 < len(pages_for_key):
                response["NextMarker"] = str(index + 1)
            return response

        kms.list_grants.side_effect = list_grants
        if pages is not None:
            kms.list_keys.side_effect = lambda **kwargs: (
                pages[1] if kwargs.get("Marker") else pages[0]
            )
        else:
            kms.list_keys.return_value = {
                "Keys": [
                    {"KeyId": key_id, "KeyArn": f"arn:k/{key_id}"}
                    for key_id in policies
                ]
            }

        def get_key_policy(KeyId, PolicyName):
            assert PolicyName == "default"
            if policy_error and KeyId in policy_error:
                raise policy_error[KeyId]
            return {"Policy": json.dumps(_policy(*policies[KeyId]))}

        kms.get_key_policy.side_effect = get_key_policy
        kms.describe_key.side_effect = lambda KeyId: {
            "KeyMetadata": {"KeyManager": (key_manager or {}).get(KeyId, "CUSTOMER")}
        }
        with patch("boto3.client", return_value=kms):
            result = bedrock_app.check_kms_enclave_key_binding(region="us-east-1")
        return result, extract_csv_data(result), kms

    # DAT-10: a debug-mode enclave presents all zeros for each PCR, so a pin
    # to zeros admits any image run in debug mode. Allow and Deny pins to the
    # zero value used to be credited as exact; the real digest still passes.
    ZERO = "0" * 96

    def test_br55_an_all_zero_allow_pin_is_not_a_measurement(self):
        zero = self._enclave_allow()
        zero["Condition"] = {
            "StringEqualsIgnoreCase": {
                "kms:RecipientAttestation:ImageSha384": self.ZERO,
                self.PCR3: self.ZERO,
            }
        }
        _, rows, _ = self._run(
            {
                "a-zero": [self._admin(), zero],
                "b-real": [self._admin(), self._enclave_allow()],
            }
        )
        assert [r["Status"] for r in rows] == ["Failed", "Passed"]
        assert "arn:k/a-zero" in rows[0]["Finding_Details"]
        assert (
            "statement 'EnclaveDecrypt' allows kms:decrypt, kms:generatedatakey "
            "with no exact attestation measurement" in rows[0]["Finding_Details"]
        )
        assert "arn:k/a-zero" not in rows[1]["Finding_Details"]

    def test_br55_an_all_zero_deny_pin_is_not_a_measurement(self):
        def zeroed(statement):
            key = next(iter(statement["Condition"]["StringNotEqualsIgnoreCase"]))
            return dict(
                statement,
                Condition={"StringNotEqualsIgnoreCase": {key: self.ZERO}},
            )

        _, rows, _ = self._run(
            {
                "a-zero": [
                    self.ROOT,
                    zeroed(self._deployment_deny()),
                    zeroed(self._image_deny()),
                ],
                "b-real": [self.ROOT, self._deployment_deny(), self._image_deny()],
            }
        )
        assert [r["Status"] for r in rows] == ["Failed", "Passed"]
        assert "arn:k/a-zero" in rows[0]["Finding_Details"]
        assert "arn:k/a-zero" not in rows[1]["Finding_Details"]

