        if status == "Failed":
            assert (
                f"{self.ROLE} (no identity policy allows s3:GetObject on the bucket "
                "and the bucket policy allows it to no one)"
            ) in rows[0]["Finding_Details"]
        if status == "N/A":
            assert (
                f"{self.ROLE}: its identity policies allow s3:GetObject on part of "
                "the bucket only"
            ) in rows[0]["Finding_Details"]

