    INVOCATION_ROOT = (
        "s3://inv-logs/bedrock/AWSLogs/123456789012/BedrockModelInvocationLogs/"
        "us-east-1/"
    )
    S3_INVOCATION = {"root": INVOCATION_ROOT, "log_group": None, "error": None}
